System.Collections.IEnumerator Run()
{
 GameMenuUI.Testing=true;
 var body=UnityEngine.Object.FindObjectOfType<Character.Lifecycle.Death>();var root=body.transform.parent;
 foreach(var rb in root.GetComponentsInChildren<UnityEngine.Rigidbody2D>())rb.simulated=false;
 foreach(var a in root.GetComponentsInChildren<Character.Control.ArmsSimulation>())a.enabled=false;
 foreach(var t in UnityEngine.Object.FindObjectsOfType<Character.Control.TargetMovement>())t.enabled=false;
 foreach(var u in root.GetComponentsInChildren<PlayerUnstuck>())u.enabled=false;
 foreach(var v in UnityEngine.Object.FindObjectsOfType<Cinemachine.CinemachineVirtualCamera>()){v.enabled=true;v.PreviousStateIsValid=false;}
 var tester=UnityEngine.Object.FindObjectsOfType<UnityEngine.MonoBehaviour>().FirstOrDefault(m=>m.GetType().Name=="GiftKeyboardTester");
 if(tester!=null)tester.GetType().GetField("visible",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)?.SetValue(tester,false);
 var camera=UnityEngine.Camera.main;var bg=camera.GetComponent<KitLandscape>();
 if(!bg||!bg.HasLayeredBackground)throw new System.Exception("Missing layers");
 var layers=camera.GetComponentsInChildren<UnityEngine.SpriteRenderer>().Where(r=>r.name.Contains(" / ")).ToArray();
 if(layers.Length!=6||layers.Any(r=>r.flipX))throw new System.Exception("Repeated/mirrored layers remain");
 for(int i=0;i<20;i++)yield return null;
 var first=root.position;var start=camera.transform.position;
 var far=layers.First(r=>r.name.StartsWith("02"));var near=layers.First(r=>r.name.StartsWith("06"));
 float farX=far.transform.localPosition.x,nearX=near.transform.localPosition.x;
 UnityEngine.ScreenCapture.CaptureScreenshot(System.IO.Path.GetFullPath("scripts/parallax-natural-20261111/start-game.png"));
 for(int i=0;i<120;i++){
  root.position=first+new UnityEngine.Vector3((i+1f)/120f*20,0,0);
  yield return new UnityEngine.WaitForSecondsRealtime(.04f);
 }
 for(int i=0;i<20;i++)yield return null;
 bg.UpdateLayers();
 float dx=camera.transform.position.x-start.x,farDx=farX-far.transform.localPosition.x,nearDx=nearX-near.transform.localPosition.x;
 if(dx<5||farDx<=0||nearDx<farDx*5)throw new System.Exception("Player-follow parallax not moving with depth: "+dx+" / "+farDx+" / "+nearDx);
 UnityEngine.ScreenCapture.CaptureScreenshot(System.IO.Path.GetFullPath("scripts/parallax-natural-20261111/moved-game.png"));
 var brain=camera.GetComponent<Cinemachine.CinemachineBrain>();brain.enabled=false;
 var range=bg.HorizontalTravelRange;var saved=camera.transform.position;float oldAspect=camera.aspect;
 void Capture(string name,int w,int h){
  var prev=camera.targetTexture;var active=UnityEngine.RenderTexture.active;var rt=new UnityEngine.RenderTexture(w,h,24);var tex=new UnityEngine.Texture2D(w,h,UnityEngine.TextureFormat.RGB24,false);
  try{camera.targetTexture=rt;camera.aspect=(float)w/h;bg.UpdateLayers();camera.Render();UnityEngine.RenderTexture.active=rt;tex.ReadPixels(new UnityEngine.Rect(0,0,w,h),0,0);tex.Apply();System.IO.File.WriteAllBytes("scripts/parallax-natural-20261111/"+name+".png",tex.EncodeToPNG());}
  finally{camera.targetTexture=prev;camera.aspect=oldAspect;UnityEngine.RenderTexture.active=active;UnityEngine.Object.Destroy(tex);rt.Release();UnityEngine.Object.Destroy(rt);}
 }
 foreach(float aspect in new[]{9f/16f,16f/9f,32f/9f})foreach(float x in new[]{range.x-10000,range.x,(range.x+range.y)*.5f,range.y,range.y+10000}){
  camera.aspect=aspect;camera.transform.position=new UnityEngine.Vector3(x,start.y+300,start.z);bg.UpdateLayers();
  foreach(var r in layers){float half=camera.orthographicSize*aspect;if(r.flipX||r.bounds.min.x>camera.transform.position.x-half+.002f||r.bounds.max.x<camera.transform.position.x+half-.002f||System.Math.Abs(r.transform.localScale.x-r.transform.localScale.y)>.00001f)throw new System.Exception("Coverage/flip/aspect failure: "+r.name);}
 }
 camera.aspect=oldAspect;camera.transform.position=new UnityEngine.Vector3(range.x,start.y,start.z);Capture("range-start",1400,800);
 camera.transform.position=new UnityEngine.Vector3((range.x+range.y)*.5f,start.y,start.z);Capture("range-middle",1400,800);Capture("portrait",720,1280);
 camera.transform.position=new UnityEngine.Vector3(range.y,start.y,start.z);Capture("range-end",1400,800);
 camera.transform.position=saved;camera.aspect=oldAspect;brain.enabled=true;root.position=first;
 for(int i=0;i<8;i++){bg.enabled=false;bg.enabled=true;}yield return null;
 if(camera.GetComponentsInChildren<UnityEngine.SpriteRenderer>().Count(r=>r.name.Contains(" / "))!=6)throw new System.Exception("Rebuild duplicates");
 string result="PASS one panorama per layer, six renderers, zero mirrors/repeats. Camera dx="+dx+", far dx="+farDx+", near dx="+nearDx+". Authored horizontal span="+range+". PASS viewport coverage at start/middle/end and beyond +/-10000m, three aspects, 300m climb; eight rebuild cycles. Physics isolated: not a traversal test. No scene or preference writes.";
 System.IO.File.WriteAllText("scripts/parallax-natural-20261111/results.txt",result);UnityEngine.Debug.Log(result);
}
return Run();
